AND
device_code = #{item.deviceCode} AND channel_code = #{item.channelCode}

update.foreach:
UPDATE vm_algorithm_give_merge_config SET
merge_id = #{item.mergeId},
sync_status = #{item.syncStatus}, fail_reason = #{item.failReason}, update_time = #{item.updateTime} WHERE id = #{item.id}

UPDATE vm_algorithm_give_merge_config
SET
delete_flag = 1,
update_time = #{item.updateTime}
WHERE id = #{item.id}
